def split_chunks(text, chunk_size=500, chunk_overlap=0):
    chunks = []
    current = ''
    for raw in text.split('\n\n'):
        para = raw.strip()
        if not para:
            continue
        if len(current) + len(para) <= chunk_size:
            current = para if not current else current + '\n\n' + para
        else:
            if current:
                chunks.append(current)
            current = para
    if current:
        chunks.append(current)
    return chunks

